
'use strict';
const BOOT=JSON.parse(document.querySelector('#jobs-boot').textContent);
let TODAY=BOOT.today;
const DRAFT_KEY='zib-jobs-draft-'+BOOT.user.id;
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',jobs:'M8 6V3h8v3 M3 7h18v14H3z M3 12c5 4 13 4 18 0 M10 12h4v4h-4z',calendar:'M4 5h16v16H4z M8 3v4 M16 3v4 M4 10h16 M8 14h1 M14 14h1 M8 18h1',files:'M5 3h9l5 5v13H5z M14 3v6h5 M8 13h8 M8 17h5',funnel:'M3 4h18l-7 9v7l-4-2v-5z',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M14 7l5 5-5 5',left:'M15 5l-7 7 7 7',right:'M9 5l7 7-7 7',close:'M6 6l12 12 M18 6L6 18',check:'M5 12l4 4L19 6',search:'M16 16l5 5 M10 17a7 7 0 1 0 0-14 7 7 0 0 0 0 14',clock:'M12 8v5l3 2 M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',link:'M10 13l4-4 M8 16l-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0 M16 8l2-2a4 4 0 0 0-6-6l-5 5',info:'M12 11v6 M12 7h.01 M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20',upload:'M12 16V4 M7 9l5-5 5 5 M4 16v5h16v-5',external:'M14 3h7v7 M21 3L10 14 M10 3H3v18h18v-7',trash:'M4 6h16 M9 6V3h6v3 M6 6l1 15h10l1-15 M10 10v7 M14 10v7',edit:'M15 4l5 5 M3 21l5-1L21 7l-5-5L3 15z',mail:'M3 5h18v14H3z M3 5l9 8 9-8'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.jobs}"/></svg>`;
const ST={saved:'Сохранено',applied:'Отклик',screen:'HR-скрининг',technical:'Техинтервью',final:'Финал',offer:'Оффер',rejected:'Отказ',withdrawn:'Снялся сам'};
const stages=['applied','screen','technical','final','offer'];
const closed=j=>['rejected','withdrawn','offer'].includes(j.status);
const dateObj=d=>new Date(d+'T12:00:00Z');
const iso=d=>d.toISOString().slice(0,10);
const shift=(d,n)=>{const x=dateObj(d);x.setUTCDate(x.getUTCDate()+n);return iso(x)};
const days=(a,b)=>Math.round((dateObj(a)-dateObj(b))/86400000);
const fmt=(d,opts={day:'numeric',month:'short'})=>d?dateObj(d).toLocaleDateString('ru-RU',{...opts,timeZone:'UTC'}):'—';
const fullDate=d=>fmt(d,{weekday:'long',day:'numeric',month:'long'});
const uid=()=>globalThis.crypto?.randomUUID?.()||'id-'+Date.now()+'-'+Math.random().toString(36).slice(2);
const statusOptions=s=>Object.entries(ST).map(([k,v])=>`<option value="${k}" ${k===s?'selected':''}>${v}</option>`).join('');
let state=BOOT.state,revision=BOOT.revision;
let view=['overview','jobs','calendar','files','funnel'].includes(location.hash.slice(1))?location.hash.slice(1):'overview',selectedDay=TODAY,month=TODAY.slice(0,7)+'-01',weekStart=startOfWeek(TODAY),jobFilter='all',search='',listMode='list',cohort='all',activeJob=null;
let toastTimer;const toastEl=$('#toast');
function toast(s,undo=null){
 const host=$('#modal').open?$('#modal'):$('#drawer').open?$('#drawer'):document.body;
 host.appendChild(toastEl);
 toastEl.innerHTML=`<span>${esc(s)}</span>${undo?`<button class="toast-undo" data-action="${esc(undo.action)}" data-id="${esc(undo.id)}">Отменить</button>`:''}`;
 clearTimeout(toastTimer);toastTimer=setTimeout(()=>toastEl.textContent='',undo?12000:4200);
}
function logo(j){const tones=['sage','sand','lilac','blue'];return `<div class="company-logo ${tones[Number(j.id.replace(/\D/g,''))%4]||'sage'}">${esc(j.company.split(' ').map(x=>x[0]).slice(0,2).join(''))}</div>`}
function badge(s){return `<span class="badge ${esc(s)}">${esc(ST[s])}</span>`}
const getJob=id=>state.jobs.find(j=>j.id===id);
const mainFiles=()=>state.files.find(f=>f.primary)||state.files[0];
const dueJobs=()=>state.jobs.filter(j=>j.next&&j.next.date<=TODAY&&!['rejected','withdrawn'].includes(j.status)).sort((a,b)=>a.next.date.localeCompare(b.next.date));
const activeJobs=()=>state.jobs.filter(j=>!closed(j)&&j.status!=='saved');
const reached=(j,s)=>j.history.some(h=>h.status===s);
function startOfWeek(day){return shift(day,-((dateObj(day).getUTCDay()+6)%7))}
const weekApplied=()=>state.jobs.filter(j=>j.applied&&j.applied>=startOfWeek(TODAY)&&j.applied<=shift(startOfWeek(TODAY),6)).length;
function nextLabel(j){if(!j.next)return '<span class="muted">Не назначено</span>';let n=days(j.next.date,TODAY);return `<span class="${n<0?'red':n===0?'orange':'muted'}">${esc(j.next.title)}<br><span class="tiny">${n<0?'Просрочено на '+Math.abs(n)+' дн.':n===0?'Сегодня':fmt(j.next.date)}</span></span>`}
function nav(){const labels={overview:'Обзор',jobs:'Отклики',calendar:'Календарь',files:'Документы',funnel:'Воронка'};$('#navigation').innerHTML=Object.entries(labels).map(([key,name])=>`<button data-view="${key}" class="${view===key?'active':''}" ${view===key?'aria-current="page"':''}>${icon(key)}${name}${key==='jobs'?`<span class="nav-count">${activeJobs().length}</span>`:''}</button>`).join('')}
function head(title,sub,action='job'){return `<div class="page-head"><div><h1>${title}</h1><p>${sub}</p></div>${action==='job'?`<button class="btn" data-action="add-job">${icon('plus')} Добавить отклик</button>`:action==='event'?`<button class="btn" data-action="add-event">${icon('plus')} Добавить событие</button>`:action==='file'?`<button class="btn" data-action="upload">${icon('upload')} Загрузить файлы</button>`:''}</div>`}
function stats(){const interviews=state.events.filter(e=>!e.done&&e.type==='interview'&&e.date>=TODAY&&e.date<=shift(startOfWeek(TODAY),6)).length;const due=dueJobs();return `<div class="stats"><div class="stat"><div class="stat-top">В процессе ${icon('jobs')}</div><strong>${activeJobs().length}</strong><small>активных откликов</small></div><div class="stat"><div class="stat-top">На этой неделе ${icon('calendar')}</div><strong>${interviews}</strong><small>предстоящих собеседований</small></div><div class="stat"><div class="stat-top">Пора действовать ${icon('clock')}</div><strong class="orange">${due.length}</strong><small>${due.filter(j=>j.next.date<TODAY).length} просроченных действия</small></div><div class="stat"><div class="stat-top">Офферы ${icon('check')}</div><strong class="green">${state.jobs.filter(j=>j.status==='offer').length}</strong><small>можно обсудить условия</small></div></div>`}
function combinedEvents(day){const events=state.events.filter(e=>e.date===day).map(e=>({...e,kind:'event'}));const tasks=state.jobs.filter(j=>j.next?.date===day&&!['rejected','withdrawn'].includes(j.status)).map(j=>({id:j.id,job:j.id,title:j.next.title,date:day,time:'',type:j.status==='saved'?'apply':'ping',done:false,kind:'task'}));return [...events,...tasks].sort((a,b)=>(a.time||'99').localeCompare(b.time||'99'))}
function agenda(day){const events=combinedEvents(day);return `<div class="day-caption">${esc(fullDate(day))} · Алматы, UTC+5</div>${events.length?events.map(e=>{const j=getJob(e.job);return `<div class="agenda-item"><div class="agenda-time">${e.time||'В день'}${e.duration?`<div class="tiny muted">${e.duration} мин</div>`:''}</div><div class="agenda-info ${e.type==='interview'?'':e.type}">${j?`<button class="text-button" data-job="${esc(e.job)}">${esc(e.title)}</button>`:`<h3>${esc(e.title)}</h3>`}<p>${esc(j?.company||'Личное событие')} ${j?'· '+esc(j.role):''}</p>${e.note?`<p>${esc(e.note)}</p>`:''}${e.done?'<span class="badge offer">Завершено</span>':''}</div>${e.done?`<button class="btn secondary small" data-action="undo-event" data-id="${esc(e.id)}" aria-label="Вернуть событие ${esc(e.title)}">↶ Вернуть</button>`:`<button class="btn secondary small" data-action="${e.kind==='task'?'complete-task':'complete-event'}" data-id="${esc(e.id)}">${icon('check')} Готово</button>`}</div>`}).join(''):'<div class="list-empty">Свободный день. Можно запланировать отклик или подготовку.</div>'}`}
function miniFunnel(){const js=state.jobs.filter(j=>j.applied&&j.status!=='saved');return ['applied','screen','technical','offer'].map(s=>{const n=js.filter(j=>reached(j,s)).length;return `<div class="mini-funnel-row"><span class="mini-funnel-label">${s==='applied'?'Отклики':s==='screen'?'HR':s==='technical'?'Техника':'Офферы'}</span><div class="mini-bar"><i style="width:${js.length?n/js.length*100:0}%"></i></div><b>${n}</b></div>`}).join('')}
function overview(){const due=dueJobs(),f=mainFiles(),wa=weekApplied();return head('Поиск работы',fullDate(TODAY)+'. Вот что требует внимания сегодня.')+stats()+`<div class="dashboard"><div><section class="panel"><div class="panel-head"><h2>Твоя неделя</h2><div class="inline"><span class="small muted">${fmt(weekStart)} — ${fmt(shift(weekStart,6))}</span><button class="close-btn" aria-label="Предыдущая неделя" data-action="week" data-n="-7">${icon('left')}</button><button class="close-btn" aria-label="Следующая неделя" data-action="week" data-n="7">${icon('right')}</button></div></div><div class="panel-body"><div class="week-days">${Array.from({length:7},(_,i)=>{const day=shift(weekStart,i),n=combinedEvents(day).length;return `<button class="week-day ${day===selectedDay?'active':''}" data-day="${day}"><small>${fmt(day,{weekday:'short'})}</small><b>${dateObj(day).getUTCDate()}</b>${Array.from({length:Math.min(n,3)||1},()=>`<i class="event-dot ${!n?'blank':''}"></i>`).join('')}</button>`}).join('')}</div>${agenda(selectedDay)}</div></section><section class="panel"><div class="panel-head"><h2 class="section-label">Следующие действия <span class="counter">${due.length}</span></h2><button class="btn ghost small" data-view="jobs">Все отклики ${icon('arrow')}</button></div>${due.length?due.map(j=>`<div class="task-row">${logo(j)}<div class="task-body"><button class="text-button" data-job="${esc(j.id)}">${esc(j.company)}<span class="due ${j.next.date<TODAY?'late':''}">${j.next.date<TODAY?Math.abs(days(j.next.date,TODAY))+' дн. назад':'Сегодня'}</span></button><p>${esc(j.next.title)}</p></div><button class="btn secondary small" data-action="snooze" data-id="${esc(j.id)}" title="Отложить на завтра">Завтра</button><button class="check-btn" data-action="complete-task" data-id="${esc(j.id)}" aria-label="Завершить действие ${esc(j.company)}">${icon('check')}</button></div>`).join(''):'<div class="empty">Все срочные действия закрыты. Хороший момент для нового отклика.</div>'}</section></div><aside><section class="focus"><div class="eyebrow">${fmt(startOfWeek(TODAY))} — ${fmt(shift(startOfWeek(TODAY),6))}</div><h2>Цель по откликам</h2><p>Отправить ${state.goal} откликов за неделю. Считаются записи с датой отклика на этой неделе.</p><div class="progress"><span style="width:${Math.min(100,wa/state.goal*100)}%"></span></div><div class="between tiny"><span class="green">${wa} из ${state.goal} откликов</span><button class="text-button tiny" data-action="goal">Изменить</button></div></section><section class="panel"><div class="panel-head"><h2>CV под рукой</h2><button class="btn ghost small" data-view="files">${icon('arrow')}<span class="sr-only">Все документы</span></button></div><div class="panel-body">${f?`<div class="file-mini"><div class="inline"><div class="file-symbol">${esc(f.name.split('.').pop().toUpperCase().slice(0,4))}</div><div style="min-width:0"><h3>${esc(f.name)}</h3><span class="tiny muted">Основной · ${Math.max(1,Math.round(f.size/1024))} КБ</span></div></div></div><button class="btn secondary small" data-action="download" data-id="${esc(f.id)}">${icon('download')} Скачать CV</button>`:'<p class="small muted">Загрузи CV, чтобы прикреплять его к откликам.</p>'}<p class="tip">В карточке вакансии сохраняется версия CV, которую ты отправил.</p></div></section><section class="panel"><div class="panel-head"><h2>Путь к офферу</h2><button class="btn ghost small" data-view="funnel">${icon('arrow')}<span class="sr-only">Открыть воронку</span></button></div><div class="panel-body">${miniFunnel()}<p class="tiny muted" style="margin-top:17px">Достигнутые этапы · за всё время</p></div></section></aside></div>`}
function filteredJobs(){return state.jobs.filter(j=>(jobFilter==='all'||jobFilter==='active'&&!closed(j)&&j.status!=='saved'||jobFilter==='due'&&j.next?.date<=TODAY&&!['rejected','withdrawn'].includes(j.status)||j.status===jobFilter)&&(!search||[j.company,j.role,j.source,j.contact].join(' ').toLowerCase().includes(search.toLowerCase())))}
function jobsContent(){const js=filteredJobs();if(!js.length)return '<div class="empty">Вакансий по этим условиям нет. Измени поиск или добавь новую.</div>';return listMode==='list'?`<div class="panel table-scroll"><table class="jobs-table"><thead><tr><th>Компания / вакансия</th><th>Этап</th><th>Отклик</th><th>Следующее действие</th><th>Вилка / месяц</th></tr></thead><tbody>${js.map(j=>`<tr data-job="${esc(j.id)}"><td><div class="inline">${logo(j)}<div class="job-name"><button class="text-button" data-job="${esc(j.id)}">${esc(j.company)} ${j.priority==='high'?'<span class="green" title="Высокий приоритет">↗</span>':''}</button><small>${esc(j.role)}</small></div></div></td><td>${badge(j.status)}</td><td>${fmt(j.applied)}<div class="tiny muted">${esc(j.source)}</div></td><td>${nextLabel(j)}</td><td>${esc(j.salary||'Не указана')}<div class="tiny muted">${esc(j.location)}</div></td></tr>`).join('')}</tbody></table></div>`:`<div class="board">${Object.entries(ST).filter(([s])=>js.some(j=>j.status===s)).map(([s,label])=>`<section class="board-col"><div class="board-head">${label}<span class="counter">${js.filter(j=>j.status===s).length}</span></div>${js.filter(j=>j.status===s).map(j=>`<button class="board-card" data-job="${esc(j.id)}"><div class="between">${logo(j)}${j.priority==='high'?'<span class="tiny green">В приоритете ↗</span>':''}</div><h3>${esc(j.company)}</h3><p>${esc(j.role)}</p><p style="margin-top:10px">${esc(j.salary)}</p><div class="foot">${j.next?esc(j.next.title)+' · '+fmt(j.next.date):'Следующий шаг не назначен'}</div></button>`).join('')}</section>`).join('')}</div>`}
function jobsView(){const filters=[['all','Все'],['active','В процессе'],['due','Пора действовать'],['saved','Сохранённые'],['offer','Офферы'],['rejected','Отказы'],['withdrawn','Снялся сам']];return head('Отклики','Вся история поиска. У каждого отклика — свой следующий шаг.')+`<div class="toolbar"><div class="search-wrap">${icon('search')}<input id="job-search" aria-label="Поиск вакансий" placeholder="Компания, позиция или контакт…" value="${esc(search)}"></div><div class="segments" aria-label="Вид списка"><button data-action="mode" data-mode="list" class="${listMode==='list'?'active':''}">Список</button><button data-action="mode" data-mode="board" class="${listMode==='board'?'active':''}">Доска</button></div><button class="btn secondary" data-action="export">${icon('download')} Экспорт</button></div><div class="filters">${filters.map(([id,label])=>`<button class="filter ${jobFilter===id?'active':''}" data-filter="${id}">${label}${id==='all'?' · '+state.jobs.length:''}</button>`).join('')}</div><div id="jobs-content">${jobsContent()}</div>`}
function calendar(){const first=dateObj(month),start=shift(month,-((first.getUTCDay()+6)%7)),cells=Array.from({length:42},(_,i)=>shift(start,i));return head('Календарь','Собеседования, отклики и напоминания в одном расписании.','event')+`<div class="calendar-layout"><section><div class="panel"><div class="panel-head"><h2 class="calendar-month-title">${fmt(month,{month:'long',year:'numeric'})}</h2><div class="inline calendar-toolbar"><button class="btn ghost small" data-action="cal-today">Сегодня</button><button class="close-btn" data-action="month" data-n="-1" aria-label="Предыдущий месяц">${icon('left')}</button><button class="close-btn" data-action="month" data-n="1" aria-label="Следующий месяц">${icon('right')}</button></div></div><div class="calendar-grid">${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map(x=>`<div class="weekday">${x}</div>`).join('')}${cells.map(day=>{const es=combinedEvents(day);return `<div class="cal-cell ${!day.startsWith(month.slice(0,7))?'outside':''} ${day===selectedDay?'selected':''}" data-day="${day}" tabindex="0" role="button" aria-label="${esc(fullDate(day))}, событий: ${es.length}"><span class="date-number ${day===TODAY?'today':''}">${dateObj(day).getUTCDate()}</span>${es.slice(0,2).map(e=>`<div class="cal-event ${e.type==='interview'?'':e.type}" title="${esc(e.title)}">${e.time?e.time+' ':''}${esc(getJob(e.job)?.company||e.title)}</div>`).join('')}${es.length>2?`<div class="tiny muted">ещё ${es.length-2}</div>`:''}</div>`}).join('')}</div></div><div class="calendar-legend"><span><i class="legend-dot"></i>Собеседование / встреча</span><span><i class="legend-dot blue"></i>Напоминание</span><span><i class="legend-dot green"></i>Отклик / подготовка</span></div></section><aside><section class="panel"><div class="panel-head"><h2>План на день</h2></div><div class="panel-body">${agenda(selectedDay)}<button class="btn secondary small" style="margin-top:18px" data-action="add-event">${icon('plus')} Запланировать</button></div></section><p class="tip">Нажми на день, чтобы увидеть детали. Напоминания из карточек вакансий появляются здесь автоматически.</p><p class="tip">Напоминания видны в этом разделе. Уведомления по почте и в мессенджерах не подключены.</p></aside></div>`}
function fileView(){return head('Документы','Несколько версий CV и сопроводительных — всегда под рукой.','file')+`<div class="info-strip">${icon('link')}<div><b style="color:var(--text)">Одна библиотека для всех откликов.</b> Для каждого документа можно включить общую ссылку и в любой момент отозвать доступ. Документы хранятся в аккаунте и скачиваются в исходном формате. Включай доступ по ссылке только для файлов, которыми хочешь поделиться.</div></div><div class="docs-grid">${state.files.map(f=>`<article class="doc-card ${f.primary?'primary':''}"><div class="between"><div class="file-symbol">${esc(f.name.split('.').pop().toUpperCase().slice(0,4))}</div>${f.primary?'<span class="badge offer">Основное CV</span>':`<button class="btn ghost small" data-action="primary" data-id="${esc(f.id)}">Сделать основным</button>`}</div><h3>${esc(f.name)}</h3><p>${esc(f.label||'Личный документ')}</p><p style="margin-top:12px">${Math.max(1,Math.round(f.size/1024))} КБ · добавлен ${fmt(f.date)}${f.shared?' · доступ по ссылке включён':' · доступ только тебе'}</p><div class="doc-actions"><button class="btn secondary small" data-action="download" data-id="${esc(f.id)}">${icon('download')} Скачать ${esc(f.name.split('.').pop().toUpperCase().slice(0,4))}</button><button class="btn ghost small" data-action="file-link" data-id="${esc(f.id)}" aria-label="Общая ссылка для ${esc(f.name)}">${icon('link')}</button><button class="btn ghost small" data-action="delete-file" data-id="${esc(f.id)}" aria-label="Удалить ${esc(f.name)}">${icon('trash')}</button></div></article>`).join('')}</div><div class="upload-zone" id="drop-zone">${icon('upload')}<h3>Перетащи файлы сюда</h3><p>PDF, DOCX, TXT или изображения · до 10 МБ на файл · можно несколько сразу</p><button class="btn secondary" data-action="upload">Выбрать файлы</button></div><p class="tip">Файлы скачиваются в исходном формате, без преобразования. До 100 файлов и 100 МБ на аккаунт. Файл CV, выбранный в карточке отклика, не меняется при смене основного.</p>`}
function funnel(){const js=state.jobs.filter(j=>j.status!=='saved'&&j.applied&&(cohort==='all'||j.applied>=shift(TODAY,-29)&&j.applied<=TODAY)),n=js.length,counts=stages.map(s=>js.filter(j=>reached(j,s)).length),rejected=js.filter(j=>j.status==='rejected').length,withdrawn=js.filter(j=>j.status==='withdrawn').length,offers=js.filter(j=>j.status==='offer').length,active=js.filter(j=>!closed(j)).length;return head('Воронка поиска','Что работает, где теряются отклики и сколько шагов до оффера.','')+`<div class="toolbar"><div class="segments"><button data-action="cohort" data-value="all" class="${cohort==='all'?'active':''}">За всё время</button><button data-action="cohort" data-value="30" class="${cohort==='30'?'active':''}">Отклики за 30 дней</button></div><span class="small muted">${n} откликов · ${cohort==='all'?(js.length?fmt(js.map(j=>j.applied).sort()[0]):'—')+' — '+fmt(TODAY):fmt(shift(TODAY,-29))+' — '+fmt(TODAY)}</span></div><div class="info-strip">${icon('info')}<div>Воронка считает <b style="color:var(--text)">достигнутые этапы</b>, включая завершённые отклики. Кандидат, получивший отказ после технического интервью, остаётся учтённым на этом этапе. Сохранённые вакансии не входят в расчёт.</div></div><div class="analytics-grid"><div><section class="panel"><div class="panel-head"><h2>От отклика до оффера</h2><span class="tiny muted">Число откликов →</span></div><div class="panel-body">${stages.map((s,i)=>`<div class="funnel-step"><span>${s==='applied'?'Откликнулись':ST[s]}</span><div class="funnel-track"><div class="funnel-fill" style="width:${n?counts[i]/n*100:0}%"></div></div><b>${counts[i]}</b><small>${n?Math.round(counts[i]/n*100):0}%</small></div>`).join('')}<p class="tiny muted">Доля от всех откликов в выбранной группе. Источник: история этапов твоих откликов.</p></div></section><section class="panel"><div class="panel-head"><h2>Переходы между этапами</h2><span class="tiny muted">Конверсия</span></div><div class="panel-body">${stages.slice(1).map((s,i)=>`<div class="breakdown-row"><span class="muted">${ST[stages[i]]} → ${ST[s]}</span><span>${counts[i+1]} из ${counts[i]} <b class="green" style="margin-left:15px">${counts[i]?Math.round(counts[i+1]/counts[i]*100)+'%':'—'}</b></span></div>`).join('')}</div></section></div><div><section class="panel"><div class="panel-head"><h2>Текущее состояние</h2><span class="tiny muted">${n} откликов</span></div><div class="panel-body"><div class="outcomes" aria-label="Активные ${active}, отказы ${rejected}, снялся ${withdrawn}, офферы ${offers}">${[[active,'#8aaabf'],[rejected,'#c9958e'],[withdrawn,'#7c8680'],[offers,'#bee59b']].map(([v,c])=>`<span style="width:${n?v/n*100:0}%;background:${c}"></span>`).join('')}</div><div class="legend-list">${[[active,'В процессе','blue'],[rejected,'Отказы','red'],[withdrawn,'Снялся сам','muted'],[offers,'Офферы','green']].map(([v,l,c])=>`<div><span class="muted"><i class="legend-dot" style="background:var(--${c==='muted'?'muted':c})"></i>${l}</span><b>${v}</b></div>`).join('')}</div></div></section><section class="panel"><div class="panel-head"><h2>Откуда приходят ответы</h2></div><div class="panel-body">${[...new Set(js.map(j=>j.source))].map(source=>{const all=js.filter(j=>j.source===source),answered=all.filter(j=>j.history.some(h=>h.status==='screen'));return `<div class="breakdown-row"><span>${esc(source)}<span class="tiny muted" style="display:block">Дошли до HR / всего откликов</span></span><span>${answered.length} / ${all.length}</span></div>`}).join('')}<p class="tiny muted" style="margin-top:13px">На малой выборке рано делать выводы об источнике.</p></div></section><section class="panel"><div class="panel-head"><h2>Отклики по неделям</h2></div><div class="panel-body"><div class="bar-chart">${Array.from({length:4},(_,i)=>shift(startOfWeek(TODAY),(i-3)*7)).map(d=>{const count=js.filter(j=>j.applied>=d&&j.applied<=shift(d,6)).length;return `<div class="chart-week"><b>${count}</b><i style="height:${Math.round(count/Math.max(1,...Array.from({length:4},(_,i)=>{const w=shift(startOfWeek(TODAY),(i-3)*7);return js.filter(j=>j.applied>=w&&j.applied<=shift(w,6)).length}))*80)}px"></i><span>${fmt(d)}</span></div>`}).join('')}</div><p class="tiny muted" style="margin-top:18px">Число откликов · начало недели<br>${fmt(shift(startOfWeek(TODAY),-21))} — ${fmt(shift(startOfWeek(TODAY),6))}.</p></div></section></div></div>`}
function render(){nav();$('#main').innerHTML=({overview,jobs:jobsView,calendar,files:fileView,funnel})[view]()+`<div class="footer-note"><span>Личные данные · Алматы, UTC+5 · ${fmt(TODAY)}</span><a href="/" class="tiny muted">← Все разделы сайта</a></div>`}
function navigate(v){view=v;history.replaceState(null,'','#'+v);render();window.scrollTo({top:0})}
function modal(title,body){const d=$('#modal');d.innerHTML=`<div class="dialog-head"><h2>${title}</h2><button class="close-btn" data-action="close-modal" aria-label="Закрыть">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;if(!d.open)d.showModal()}
function endButtons(label='Сохранить'){return `<div class="dialog-foot"><button type="button" class="btn secondary" data-action="close-modal">Отмена</button><button class="btn" type="submit">${label}</button></div>`}
function jobForm(id){const j=getJob(id)||{},f=mainFiles();modal(id?'Редактировать вакансию':'Новый отклик',`<form id="job-form" data-id="${esc(id||'')}"><div class="form-grid"><label class="field">Компания<input name="company" required maxlength="100" value="${esc(j.company||'')}" placeholder="Например, Northstar"></label><label class="field">Позиция<input name="role" required maxlength="150" value="${esc(j.role||'')}" placeholder="Senior Python Engineer"></label><label class="field full">Ссылка на вакансию<input name="url" type="url" value="${esc(j.url||'')}" placeholder="https://…"></label><label class="field">Статус<select name="status">${statusOptions(j.status||'applied')}</select></label><label class="field">Дата отклика<input name="applied" type="date" max="${TODAY}" value="${esc(j.applied??TODAY)}"><span>Для сохранённой вакансии можно оставить пустой.</span></label><label class="field">Вилка / месяц<input name="salary" value="${esc(j.salary||'')}" placeholder="$5 000–6 500 · gross"></label><label class="field">Формат / география<input name="location" value="${esc(j.location||'')}" placeholder="Remote · EMEA"></label><label class="field">Источник<select name="source">${['LinkedIn','Telegram','Рекомендация','Карьерный сайт','Другое'].map(s=>`<option ${j.source===s?'selected':''}>${s}</option>`).join('')}</select></label><label class="field">Приоритет<select name="priority"><option value="normal">Обычный</option><option value="high" ${j.priority==='high'?'selected':''}>Высокий</option></select></label><label class="field full">Контакт рекрутера<input name="contact" value="${esc(j.contact||'')}" placeholder="Имя, email или Telegram"></label><label class="field full">Отправленная версия CV<select name="cv"><option value="">Без файла</option>${state.files.map(file=>`<option value="${esc(file.id)}" ${file.id===(j.cv??f?.id)?'selected':''}>${esc(file.name)}</option>`).join('')}</select></label>${!id?'<label class="field full"><span><input name="remind" type="checkbox" checked style="width:auto;margin-right:7px"> Напомнить через 7 дней после отклика</span></label>':''}</div>${endButtons(id?'Сохранить изменения':'Добавить отклик')}</form>`)}
function eventForm(jobId){modal('Запланировать событие',`<form id="event-form"><div class="form-grid"><label class="field full">Событие<input name="title" required maxlength="150" placeholder="Например, техническое интервью"></label><label class="field full">Вакансия<select name="job"><option value="">Без вакансии</option>${state.jobs.map(j=>`<option value="${esc(j.id)}" ${j.id===jobId?'selected':''}>${esc(j.company)} · ${esc(j.role)}</option>`).join('')}</select></label><label class="field">Тип<select name="type"><option value="interview">Собеседование / встреча</option><option value="ping">Напоминание</option><option value="apply">Отклик / подготовка</option></select></label><label class="field">Дата<input type="date" name="date" required value="${selectedDay}"></label><label class="field">Время в Алматы<input type="time" name="time" value="14:00" required></label><label class="field">Длительность, минут<input type="number" min="5" max="480" name="duration" value="60" required></label><label class="field full">Заметка / ссылка на встречу<textarea name="note" placeholder="Что подготовить, кто проводит встречу…"></textarea></label></div><p class="tip">Время указано в Алматы (UTC+5). Встречи и напоминания видны в календаре и на обзоре.</p>${endButtons('Добавить событие')}</form>`)}
function openJob(id){const j=getJob(id);if(!j)return;activeJob=id;const f=state.files.find(f=>f.id===j.cv);const d=$('#drawer');d.innerHTML=`<div class="dialog-head"><span class="small muted">Карточка вакансии</span><div class="inline"><button class="close-btn" data-action="edit-job" data-id="${esc(j.id)}" aria-label="Редактировать">${icon('edit')}</button><button class="close-btn" data-action="close-drawer" aria-label="Закрыть карточку">${icon('close')}</button></div></div><div class="dialog-body"><div class="drawer-job"><div class="between">${logo(j)}${badge(j.status)}</div><h2>${esc(j.company)}</h2><p>${esc(j.role)}</p>${j.priority==='high'?'<span class="badge offer" style="margin-top:12px">В приоритете ↗</span>':''}<select class="status-select" id="job-status" aria-label="Статус вакансии">${statusOptions(j.status)}</select></div><dl class="detail-grid"><div><dt>Вилка / месяц</dt><dd>${esc(j.salary||'Не указана')}</dd></div><div><dt>Формат</dt><dd>${esc(j.location||'Не указан')}</dd></div><div><dt>Дата отклика</dt><dd>${fmt(j.applied)}</dd></div><div><dt>Последний контакт</dt><dd>${fmt(j.lastContact)}</dd></div><div><dt>Источник</dt><dd>${esc(j.source)}</dd></div><div><dt>Отправленный CV</dt><dd>${f?`<button class="text-button tiny green" data-action="download" data-id="${esc(f.id)}">${esc(f.name)}</button>`:'Без прикреплённого файла'}</dd></div><div style="grid-column:1/-1"><dt>Контакт</dt><dd>${esc(j.contact||'Добавь контакт через редактирование')}</dd></div>${j.url?`<div style="grid-column:1/-1"><dt>Вакансия</dt><dd><a href="${esc(safeUrl(j.url))}" target="_blank" rel="noopener noreferrer">Открыть объявление ↗</a></dd></div>`:''}</dl>${j.reason?`<div class="info-strip"><div><span class="red">${j.status==='withdrawn'?'Почему снялся':'Причина отказа'}</span><p>${esc(j.reason)}</p></div></div>`:''}<div class="between" style="margin-bottom:20px"><span class="tiny muted">Обновить дату общения с компанией</span><button class="btn secondary small" data-action="contact" data-id="${esc(j.id)}">${icon('mail')} Контакт сегодня</button></div><section class="drawer-section"><h3>Следующее действие</h3>${j.next?`<div class="next-card"><small>${esc(fullDate(j.next.date))}${j.next.date<TODAY?' · просрочено':''}</small><p>${esc(j.next.title)}</p><div class="inline"><button class="btn small" data-action="complete-task" data-id="${esc(j.id)}">${icon('check')} Выполнено</button><button class="btn secondary small" data-action="snooze-week" data-id="${esc(j.id)}">Через неделю</button></div></div>`:'<p class="small muted">Пока не назначено.</p>'}<form id="next-form" style="margin-top:15px"><div class="form-grid"><label class="field full">Что сделать<input name="title" required maxlength="160" placeholder="Написать рекрутеру, подготовиться…" value="${esc(j.next?.title||'Напомнить о себе')}"></label><label class="field">Когда<input name="date" type="date" required value="${j.next?.date||shift(j.lastContact||TODAY,7)}"></label><div class="field" style="justify-content:end"><button type="button" class="btn secondary small" data-action="week-contact" data-id="${esc(j.id)}">+7 дней от контакта</button></div></div><button class="btn secondary small" type="submit">Сохранить действие</button></form></section><section class="drawer-section"><div class="between" style="margin-bottom:12px"><h3 style="margin:0">Собеседования и события</h3><button class="btn ghost small" data-action="add-job-event" data-id="${esc(j.id)}">${icon('plus')} Добавить</button></div>${state.events.filter(e=>e.job===j.id).sort((a,b)=>a.date.localeCompare(b.date)).map(e=>`<div class="note-entry"><small>${fmt(e.date)} · ${esc(e.time)} · ${e.done?'Завершено':e.duration+' мин'}</small>${esc(e.title)}${e.note?`<p class="tiny muted" style="margin-top:5px">${esc(e.note)}</p>`:''}<div class="inline" style="margin-top:7px">${e.done?`<button class="btn secondary small" data-action="undo-event" data-id="${esc(e.id)}">↶ Вернуть</button>`:`<button class="btn secondary small" data-action="complete-event" data-id="${esc(e.id)}">Завершить</button>`}<button class="btn ghost small" data-action="delete-event" data-id="${esc(e.id)}">Удалить</button></div></div>`).join('')||'<p class="small muted">Здесь появятся встречи по этой вакансии.</p>'}</section><section class="drawer-section"><h3>Заметки</h3>${j.notes.map(n=>`<div class="note-entry"><small>${fmt(n.date)}</small>${esc(n.text)}</div>`).join('')}<form id="note-form"><label class="field"><span class="sr-only">Новая заметка</span><textarea name="text" required maxlength="6000" placeholder="Впечатления от интервью, вопросы, договорённости…"></textarea></label><button class="btn secondary small" type="submit">Добавить заметку</button></form></section><section class="drawer-section"><h3>История</h3>${[...j.history].reverse().map(h=>`<div class="timeline-row">${esc(h.text||ST[h.status]||'Обновление')}<small>${fmt(h.date)}</small>${h.completedTask&&!j.next?`<button class="btn ghost small" data-action="undo-task" data-id="${esc(h.id)}">↶ Вернуть действие</button>`:''}</div>`).join('')}</section><div class="between"><button class="btn ghost small red" data-action="delete-job" data-id="${esc(j.id)}">${icon('trash')} Удалить вакансию</button><button class="btn ghost small" data-action="edit-job" data-id="${esc(j.id)}">Редактировать</button></div></div>`;if(!d.open)d.showModal()}
function safeUrl(url){try{const u=new URL(url);return ['http:','https:'].includes(u.protocol)?u.href:'#'}catch{return '#'}}
function refresh(){save();render();if($('#drawer').open&&getJob(activeJob))openJob(activeJob)}
function completeTask(id){
 const j=getJob(id);if(!j?.next)return;
 const entry={id:uid(),date:TODAY,text:'Выполнено: '+j.next.title,completedTask:{...j.next}};
 j.history.push(entry);j.next=null;refresh();
 toast('Действие выполнено.',{action:'undo-task',id:entry.id});
}
function undoTask(id){
 const j=state.jobs.find(j=>j.history.some(h=>h.id===id&&h.completedTask));if(!j)return;
 if(j.next){toast('У вакансии уже назначено другое действие. Измени его в карточке.');return}
 const entry=j.history.find(h=>h.id===id);j.next={...entry.completedTask};
 j.history=j.history.filter(h=>h.id!==id);refresh();toast('Действие возвращено с прежней датой.');
}
function completeEvent(id){
 const e=state.events.find(e=>e.id===id);if(!e||e.done)return;
 e.done=true;const j=getJob(e.job);
 if(j){const entry={id:uid(),eventId:e.id,date:e.date,text:'Завершено: '+e.title,contactDate:e.date,previousContact:j.lastContact};e.completionId=entry.id;j.history.push(entry);j.lastContact=e.date}
 refresh();toast('Событие завершено.',{action:'undo-event',id});
}
function undoEvent(id){
 const e=state.events.find(e=>e.id===id);if(!e?.done)return;
 const j=getJob(e.job);
 if(j){
  // Поддерживаем также завершения, сохранённые до появления кнопки отмены.
  const index=e.completionId?j.history.findIndex(h=>h.id===e.completionId):j.history.findLastIndex(h=>h.text==='Завершено: '+e.title&&h.date===e.date);
  if(index>=0){
   const entry=j.history[index];
   const previous=entry.previousContact??j.history.slice(0,index).filter(h=>h.status||h.contactDate||h.text==='Отмечен контакт с компанией'||h.text?.startsWith('Завершено: ')).map(h=>h.contactDate||h.date).at(-1)??j.applied??TODAY;
   const nextContact=j.history.slice(index+1).find(h=>h.status||h.contactDate||h.text==='Отмечен контакт с компанией'||h.text?.startsWith('Завершено: '));
   // Более позднее общение сохраняем; при отмене нескольких встреч перепривязываем снимок предыдущей даты.
   if(nextContact&&Object.hasOwn(nextContact,'previousContact'))nextContact.previousContact=previous;
   if(!nextContact&&j.lastContact===(entry.contactDate||e.date))j.lastContact=previous;
   j.history.splice(index,1);
  }
 }
 e.done=false;delete e.completionId;refresh();toast('Завершение отменено. Событие снова в плане.');
}
function changeStatus(id,status){const j=getJob(id),prev=j.status;if(prev===status)return;
// Достижение позднего этапа означает, что предыдущие этапы пройдены.
const rank=stages.indexOf(status);if(rank>=0){if(!j.applied)j.applied=TODAY;stages.slice(0,rank+1).forEach(s=>{if(!reached(j,s))j.history.push({status:s,date:TODAY})});if(reached(j,status)&&j.history.at(-1)?.status!==status)j.history.push({status,date:TODAY});}else j.history.push({status,date:TODAY});
j.status=status;j.lastContact=TODAY;if(['rejected','withdrawn'].includes(status)){j.next=null;state.events=state.events.filter(e=>e.job!==id||e.done||e.date<TODAY)}
refresh();toast('Этап обновлён. Воронка пересчитана.');if(['rejected','withdrawn'].includes(status))modal(status==='rejected'?'Что стало причиной отказа?':'Почему решил сняться?',`<form id="reason-form" data-id="${esc(id)}"><label class="field">Необязательно<textarea name="reason" placeholder="Эта заметка поможет заметить повторяющиеся причины">${esc(j.reason)}</textarea></label>${endButtons('Сохранить причину')}</form>`)}
function confirmBox(title,text,action,id){modal(title,`<p class="small muted">${text}</p><div class="dialog-foot"><button class="btn secondary" data-action="close-modal">Отмена</button><button class="btn danger" data-action="${action}" data-id="${esc(id||'')}">Удалить</button></div>`)}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000)}
async function uploadFiles(files){let count=0;for(const file of files){if(file.size>10*1024*1024){toast('Файл больше 10 МБ: '+file.name);continue}try{const saved=await api('/jobs/api/files?name='+encodeURIComponent(file.name),{method:'POST',body:file,headers:{'Content-Type':'application/octet-stream'}});state.files.push(saved);count++}catch(error){toast(error.message);break}}render();if(count)toast('Сохранено файлов: '+count);$('#upload').value=''}
const actions={
'add-job':()=>jobForm(), 'edit-job':id=>jobForm(id), 'add-event':()=>eventForm(), 'add-job-event':id=>eventForm(id),
'close-modal':()=>$('#modal').close(),'close-drawer':()=>$('#drawer').close(),
'mode':(_,el)=>{listMode=el.dataset.mode;render()}, 'cohort':(_,el)=>{cohort=el.dataset.value;render()},
'week':(_,el)=>{weekStart=shift(weekStart,Number(el.dataset.n));selectedDay=weekStart;render()},
'month':(_,el)=>{const d=dateObj(month);d.setUTCMonth(d.getUTCMonth()+Number(el.dataset.n));month=iso(d);render()},
'cal-today':()=>{selectedDay=TODAY;month=TODAY.slice(0,7)+'-01';render()},
'complete-task':completeTask,
'undo-task':undoTask,
'undo-event':undoEvent,
'contact':id=>{const j=getJob(id);j.lastContact=TODAY;j.history.push({date:TODAY,text:'Отмечен контакт с компанией'});if(!['rejected','withdrawn','offer'].includes(j.status))j.next={title:'Напомнить о себе',date:shift(TODAY,7)};refresh();toast('Контакт отмечен'+(!closed(j)?'. Следующее напоминание — через неделю.':'.'))},
'snooze':id=>{const j=getJob(id);j.next.date=shift(TODAY,1);refresh();toast('Действие перенесено на завтра')},
'snooze-week':id=>{const j=getJob(id);j.next.date=shift(TODAY,7);refresh();toast('Действие перенесено на '+fmt(shift(TODAY,7)))},
'week-contact':id=>{const j=getJob(id);$('#next-form [name=date]').value=shift(j.lastContact||TODAY,7);toast('Срок рассчитан от последнего контакта')},
'complete-event':completeEvent,
'delete-event':id=>confirmBox('Удалить событие?','Событие исчезнет из календаря.','confirm-delete-event',id),
'confirm-delete-event':id=>{state.events=state.events.filter(e=>e.id!==id);$('#modal').close();refresh();toast('Событие удалено')},
'upload':()=>$('#upload').click(),
'primary':async id=>{await api('/jobs/api/files/'+encodeURIComponent(id)+'/primary',{method:'POST'});state.files.forEach(f=>f.primary=f.id===id);render();toast('Основное CV изменено. Отправленные версии в прошлых откликах сохранены.')},
'download':id=>{const a=document.createElement('a');a.href='/jobs/api/files/'+encodeURIComponent(id)+'/download';document.body.appendChild(a);a.click();a.remove()},
'file-link':id=>shareDialog(id),
'delete-file':id=>{const f=state.files.find(f=>f.id===id);const uses=state.jobs.filter(j=>j.cv===id).length;confirmBox('Удалить документ?',`«${esc(f.name)}». ${uses?'Он связан с '+uses+' откликами: связь с файлом будет убрана, история этапов сохранится.':'Документ исчезнет из библиотеки.'}`,'confirm-delete-file',id)},
'confirm-delete-file':async id=>{await flushSaves();const result=await api('/jobs/api/files/'+encodeURIComponent(id),{method:'DELETE'});revision=result.revision;const f=state.files.find(f=>f.id===id);state.files=state.files.filter(f=>f.id!==id);if(f.primary&&state.files.length)state.files[0].primary=true;state.jobs.forEach(j=>{if(j.cv===id)j.cv=''});$('#modal').close();render();toast('Документ удалён. Все общие ссылки отключены.')},
'delete-job':id=>confirmBox('Удалить вакансию?',`«${esc(getJob(id).company)}», её заметки и связанные события будут удалены из твоего списка.`,'confirm-delete-job',id),
'confirm-delete-job':id=>{state.jobs=state.jobs.filter(j=>j.id!==id);state.events=state.events.filter(e=>e.job!==id);$('#modal').close();$('#drawer').close();activeJob=null;refresh();toast('Вакансия удалена')},
'export':()=>exportState(state,'job-search.json'),
'goal':()=>modal('Цель на неделю',`<form id="goal-form"><label class="field">Сколько откликов отправить за неделю<input type="number" name="goal" required min="1" max="100" value="${state.goal}"></label>${endButtons()}</form>`),
};
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action],[data-view],[data-job],[data-day],[data-filter]');if(!el)return;try{if(el.dataset.action){await actions[el.dataset.action]?.(el.dataset.id,el);return}if(el.dataset.view){navigate(el.dataset.view);return}if(el.dataset.job){openJob(el.dataset.job);return}if(el.dataset.day){selectedDay=el.dataset.day;render();return}if(el.dataset.filter){jobFilter=el.dataset.filter;render()}}catch(err){console.error(err);toast(err.message||'Не удалось выполнить действие. Попробуй ещё раз.')}});
document.addEventListener('keydown',e=>{if(['Enter',' '].includes(e.key)&&e.target.matches('.cal-cell')){e.preventDefault();e.target.click()}});
document.addEventListener('input',e=>{if(e.target.id==='job-search'){search=e.target.value;$('#jobs-content').innerHTML=jobsContent()}});
document.addEventListener('change',e=>{if(e.target.id==='job-status')changeStatus(activeJob,e.target.value)});
$('#upload').addEventListener('change',e=>uploadFiles([...e.target.files]));
document.addEventListener('dragover',e=>{if(e.target.closest('#drop-zone')){e.preventDefault();$('#drop-zone').classList.add('drag')}});
document.addEventListener('dragleave',e=>{if(e.target.closest('#drop-zone'))$('#drop-zone').classList.remove('drag')});
document.addEventListener('drop',e=>{if(e.target.closest('#drop-zone')){e.preventDefault();uploadFiles([...e.dataTransfer.files])}});
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
document.addEventListener('submit',e=>{const form=e.target;const known=['job-form','event-form','note-form','next-form','reason-form','goal-form'];if(!known.includes(form.id))return;e.preventDefault();const data=Object.fromEntries(new FormData(form));
if(form.id==='job-form'){
data.company=data.company.trim();data.role=data.role.trim();if(!data.company||!data.role){toast('Заполни компанию и позицию');return}if(data.url&&safeUrl(data.url)==='#'){toast('Нужна ссылка с http:// или https://');return}if(data.status!=='saved'&&!data.applied){toast('Укажи дату отклика');return}const j=getJob(form.dataset.id);
if(j){const status=data.status;delete data.status;delete data.remind;Object.assign(j,data);$('#modal').close();if(status!==j.status)changeStatus(j.id,status);else refresh();if($('#drawer').open)openJob(j.id);toast('Вакансия обновлена')}
else{const j={...data,id:uid(),history:[],notes:[],next:null,lastContact:data.applied||TODAY,reason:''};delete j.remind;if(j.status==='saved'){j.applied='';j.history=[{status:'saved',date:TODAY}]}else{const rank=stages.indexOf(j.status);j.history=stages.slice(0,Math.max(0,rank)+1).map(status=>({status,date:j.applied}));if(rank<0)j.history.push({status:j.status,date:j.applied});if(data.remind&&!closed(j))j.next={title:'Напомнить об отклике',date:shift(j.applied,7)}}state.jobs.unshift(j);$('#modal').close();refresh();openJob(j.id);toast('Отклик добавлен'+(j.next?' · напоминание через 7 дней':''))}}
if(form.id==='event-form'){state.events.push({...data,duration:Number(data.duration),id:uid(),done:false});$('#modal').close();refresh();toast('Событие добавлено в календарь')}
if(form.id==='note-form'){if(!data.text.trim())return;getJob(activeJob).notes.push({date:TODAY,text:data.text.trim()});refresh();toast('Заметка сохранена')}
if(form.id==='next-form'){if(!data.title.trim())return;getJob(activeJob).next={title:data.title.trim(),date:data.date};refresh();toast('Следующее действие сохранено')}
if(form.id==='reason-form'){getJob(form.dataset.id).reason=data.reason.trim();$('#modal').close();refresh();toast('Причина сохранена')}
if(form.id==='goal-form'){state.goal=Number(data.goal);$('#modal').close();refresh();toast('Цель обновлена')}
});
window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(['overview','jobs','calendar','files','funnel'].includes(v)){view=v;render()}});

// The server owns persistence; an optimistic revision prevents one tab overwriting another.
let pendingSave=null,saving=false,saveError=null,savePromise=Promise.resolve();
function workspaceDocument(){return JSON.parse(JSON.stringify({version:1,jobs:state.jobs,events:state.events,goal:state.goal}))}
function exportState(value,name){downloadBlob(new Blob([JSON.stringify({exportedAt:new Date().toISOString(),...value},null,2)],{type:'application/json'}),name)}
async function api(url,options={}){
 const headers=new Headers(options.headers||{});
 if(options.method&&options.method!=='GET'){
  const raw=document.cookie.split('; ').find(s=>s.startsWith('csrf_token='));
  headers.set('X-CSRF-Token',raw?decodeURIComponent(raw.slice(11)):'');
  if(typeof options.body==='string')headers.set('Content-Type','application/json');
 }
 let response;try{response=await fetch(url,{...options,headers,credentials:'same-origin',cache:'no-store'})}catch{throw new Error('Нет связи с сервером. Изменения остаются в черновике.')}
 let data;try{data=await response.json()}catch{data={detail:'Сервер вернул неожиданный ответ. Обновите страницу.'}}
 if(!response.ok){const error=new Error(typeof data.detail==='string'?data.detail:'Не удалось сохранить данные. Проверь поля.');error.status=response.status;throw error}
 return data;
}
function rememberDraft(){try{localStorage.setItem(DRAFT_KEY,JSON.stringify({revision,state:workspaceDocument()}))}catch{}}
function forgetDraft(){try{localStorage.removeItem(DRAFT_KEY)}catch{}}
function paintSync(){
 const label=$('#save-status');if(label)label.textContent=saveError?'Есть несохранённые изменения':saving||pendingSave?'Сохраняю…':'Сохранено на сервере';
 const warning=$('#sync-warning');if(!warning)return;warning.hidden=!saveError;
 if(saveError)warning.innerHTML=`<span>${esc(saveError.message)}</span><button class="btn secondary small" data-action="download-draft">Скачать черновик</button>${saveError.status===409?'<button class="btn secondary small" data-action="reload-state">Обновить страницу</button>':'<button class="btn secondary small" data-action="retry-save">Повторить сохранение</button>'}`;
}
function save(){pendingSave=workspaceDocument();rememberDraft();if(!saving&&!saveError)savePromise=drainSaves();paintSync();return !saveError}
async function drainSaves(){
 saving=true;paintSync();
 try{while(pendingSave){const document=pendingSave;pendingSave=null;const result=await api('/jobs/api/state',{method:'PUT',body:JSON.stringify({revision,state:document})});revision=result.revision;if(pendingSave)rememberDraft();else forgetDraft()}}
 catch(error){saveError=error;pendingSave=workspaceDocument();rememberDraft();toast(error.message)}
 finally{saving=false;paintSync()}
}
async function flushSaves(){await savePromise;if(saveError)throw saveError;if(pendingSave){savePromise=drainSaves();await savePromise;if(saveError)throw saveError}}
function shareDialog(id){
 const file=state.files.find(f=>f.id===id);if(!file)return;
 const url=file.share_url?new URL(file.share_url,location.origin).href:'';
 modal('Доступ к документу по ссылке',`<h3 style="overflow-wrap:anywhere">${esc(file.name)}</h3><p class="tip">Любой, у кого есть ссылка, сможет скачать этот файл без входа. Доступ можно отключить в любой момент.</p>${url?`<label class="field" style="margin-top:18px">Общая ссылка<input id="share-url" readonly value="${esc(url)}"></label><div class="dialog-foot"><button class="btn secondary" data-action="unshare-file" data-id="${esc(id)}">Отключить доступ</button><button class="btn" data-action="copy-share" data-id="${esc(id)}">Скопировать ссылку</button></div>`:`<div class="dialog-foot"><button class="btn secondary" data-action="close-modal">Отмена</button><button class="btn" data-action="share-file" data-id="${esc(id)}">Включить доступ по ссылке</button></div>`}`);
}
Object.assign(actions,{
 'share-file':async id=>{const file=await api('/jobs/api/files/'+encodeURIComponent(id)+'/share',{method:'POST'});Object.assign(state.files.find(f=>f.id===id),file);shareDialog(id);toast('Доступ по ссылке включён')},
 'unshare-file':async id=>{await api('/jobs/api/files/'+encodeURIComponent(id)+'/share',{method:'DELETE'});Object.assign(state.files.find(f=>f.id===id),{shared:false,share_url:''});shareDialog(id);toast('Прежняя ссылка больше не работает')},
 'copy-share':async id=>{const file=state.files.find(f=>f.id===id);try{await navigator.clipboard.writeText(new URL(file.share_url,location.origin).href);toast('Ссылка скопирована')}catch{const input=$('#share-url');input.focus();input.select();toast('Выделенная ссылка готова к копированию')}},
 'download-draft':()=>exportState({state:workspaceDocument(),revision},'job-search-draft.json'),
 'reload-state':()=>{exportState({state:workspaceDocument(),revision},'job-search-draft.json');forgetDraft();pendingSave=null;saveError=null;saving=false;location.reload()},
 'retry-save':async()=>{saveError=null;savePromise=drainSaves();await savePromise;if(!saveError)toast('Изменения сохранены')},
 'recover-draft':()=>{const draft=readDraft();if(!draft||draft.revision!==revision)return;Object.assign(state,draft.state);$('#modal').close();save();render()},
 'discard-draft':()=>{forgetDraft();$('#modal').close()},
 'export-old-draft':()=>{const draft=readDraft();if(draft)exportState(draft,'job-search-recovery.json')}
});
function readDraft(){try{const d=JSON.parse(localStorage.getItem(DRAFT_KEY));if(d&&Number.isInteger(d.revision)&&Array.isArray(d.state?.jobs)&&Array.isArray(d.state?.events))return d}catch{}return null}
window.addEventListener('beforeunload',event=>{if(saving||pendingSave||saveError){event.preventDefault();event.returnValue=''}});
// Refresh the calendar date without discarding another edit or silently replacing server data.
setInterval(()=>{const parts=new Intl.DateTimeFormat('en-CA',{timeZone:BOOT.timezone,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const day=['year','month','day'].map(k=>parts.find(p=>p.type===k).value).join('-');if(day!==TODAY){const previous=TODAY;TODAY=day;if(selectedDay===previous)selectedDay=day;render()}},60000);
render();paintSync();
const recoverable=readDraft();
if(recoverable)modal('Есть несохранённый черновик',`<p class="small muted">${recoverable.revision===revision?'Предыдущие изменения не успели сохраниться. Можно восстановить их или оставить данные сервера.':'После этого черновика данные на сервере изменились. Скачай черновик для сверки: он не заменит новые записи автоматически.'}</p><div class="dialog-foot wrap"><button class="btn secondary" data-action="export-old-draft">Скачать черновик</button><button class="btn secondary" data-action="discard-draft">Оставить данные сервера</button>${recoverable.revision===revision?'<button class="btn" data-action="recover-draft">Восстановить</button>':''}</div>`);
